// Анализ показаний датчика (код сгенерирован с помощью AI и проверен вручную)
// Используются: let/const, if/else, цикл for, массив, объект
const student = 'Дусов, СПД ИИ-241';
const readingsSets = [
  { name: 'Склад №1', readings: [21.5, 24.0, 27.3, 26.1, 23.8] },
  { name: 'Склад №2', readings: [28.4, 30.1, 26.9, 29.5] },
];
const threshold = 25;            // порог «высокой» температуры, °C

const result = [];
for (const set of readingsSets) {
  let sum = 0;
  let max = -Infinity;
  let min = Infinity;
  const above = [];              // массив значений выше порога
  for (let i = 0; i < set.readings.length; i++) {
    const value = set.readings[i];
    sum += value;
    if (value > max) max = value;
    if (value < min) min = value;
    if (value > threshold) {
      above.push(value);
    }
  }
  const avg = set.readings.length ? sum / set.readings.length : 0;
  let status;
  if (set.readings.length === 0) {
    status = 'empty';
  } else if (avg > threshold) {
    status = 'high';
  } else {
    status = 'normal';
  }
  // Результат — объект с полем payload
  result.push({
    json: {
      topic: 'lab4/dusov/code',
      payload: {
        student,
        sensor: set.name,
        count: set.readings.length,
        avg: Number(avg.toFixed(2)),
        min,
        max,
        aboveThreshold: above,
        status,
      },
    },
  });
}
return result;
